"""Native Kaggle T4 build and GPU check of qiskit-aer-gpu-cu13 0.18.2 (docs/local/aer-cu13-kaggle/src/build.sh)."""
PAYLOAD = ''
import base64, io, subprocess, tarfile, time
from pathlib import Path
R = Path("/kaggle/tmp/recipe"); R.mkdir(parents=True, exist_ok=True)
tarfile.open(fileobj=io.BytesIO(base64.b64decode(PAYLOAD))).extractall(R)
t = time.time()
with open("/kaggle/working/build-sh.log", "w") as f:
    rc = subprocess.run(["timeout", "-k", "60", "39600", "sh", str(R / "build.sh")], stdout=f, stderr=subprocess.STDOUT).returncode
Path("/kaggle/working/result.txt").write_text(f"rc {rc}\nseconds {time.time() - t:.0f}\n")
print(open("/kaggle/working/build-sh.log").read()[-4000:]); print("rc", rc)
